"use client";

import { useState, type ComponentType } from "react";

import type { ImageProps } from "@/components/image";
import { ImageWithFallback } from "@/components/image-with-fallback";
import { Lightbox } from "@/components/lightbox";
import { cn } from "@/components/utils/cn";

import { MenuLabelBadge } from "./label-badge";
import { MenuLabelOptions } from "./label-options";
import { getMenuFilterLabels } from "./label-presets";
import { menusLabels, type MenusLabels } from "./labels";
import { menuPriceFormatter } from "./price";
import { MenuSizePrices } from "./size-prices";
import { MenuSpiceBadge } from "./spice-badge";
import type { MenuViewCategory, MenuViewLabel } from "./types";
import { outlineButton } from "./ui";

export interface MenuFilters {
  allergen: string[];
  dietary: string[];
}
export interface ComposedMenuPageProps {
  sections: readonly MenuViewCategory[];
  locale: string;
  currency: string;
  currencyLabel?: string;
  title?: string;
  description?: string;
  filterLabels?: readonly MenuViewLabel[];
  imageUrl?: (itemId: string) => string;
  imageComponent?: ComponentType<ImageProps>;
  labels?: Partial<MenusLabels>;
  className?: string;
  displayMode?: "lines" | "photos";
  filters?: MenuFilters;
  onFiltersChange?: (filters: MenuFilters) => void;
  hideHeading?: boolean;
  sectionHeadingLevel?: 2 | 3 | 4;
}

export function ComposedMenuPage({
  sections,
  locale,
  currency,
  currencyLabel = currency,
  title,
  description,
  filterLabels,
  imageUrl,
  imageComponent: MenuImage,
  labels: overrides,
  className,
  displayMode = "lines",
  filters,
  onFiltersChange,
  hideHeading = false,
  sectionHeadingLevel = 2,
}: ComposedMenuPageProps) {
  const CategoryHeading = `h${sectionHeadingLevel}` as const;
  const DishHeading = `h${sectionHeadingLevel + 1}` as "h3" | "h4" | "h5";
  const labels = { ...menusLabels, ...overrides };
  const [localFilters, setLocalFilters] = useState<MenuFilters>({ allergen: [], dietary: [] });
  const selected = filters ?? localFilters;
  const setFilters = (next: MenuFilters) =>
    onFiltersChange ? onFiltersChange(next) : setLocalFilters(next);
  const withPhotos = displayMode === "photos";
  const options = getMenuFilterLabels(sections, locale, filterLabels);
  const allergen = selected.allergen.filter((id) => options.some((label) => label.id === id));
  const dietary = selected.dietary.filter((id) => options.some((label) => label.id === id));
  const hasFilters = !!(allergen.length || dietary.length);
  const filtered = sections
    .map((section) => ({
      ...section,
      items: section.items.filter(
        (item) =>
          !item.labels.some((label) => label.kind === "allergen" && allergen.includes(label.id)) &&
          dietary.every((id) =>
            item.labels.some((label) => label.kind === "dietary" && label.id === id),
          ),
      ),
    }))
    .filter((section) => section.items.length);
  const count = filtered.reduce((total, section) => total + section.items.length, 0);
  const money = menuPriceFormatter(locale, currency);
  const hasPrices = filtered.some((section) =>
    section.items.some((item) => item.priceMinor !== null || item.sizes?.length),
  );
  return (
    <section
      className={cn(
        "mx-auto w-full max-w-6xl space-y-8 px-4 py-8 text-foreground sm:px-6",
        className,
      )}
    >
      {(!hideHeading || hasPrices) && (
        <header className="flex flex-wrap items-baseline justify-between gap-2">
          {!hideHeading && (
            <h1 className="font-serif text-3xl font-semibold">{title ?? labels.menu}</h1>
          )}
          {hasPrices && (
            <p className="ml-auto text-sm text-muted-foreground">
              {labels.price} ({currencyLabel})
            </p>
          )}
        </header>
      )}
      {description && (
        <p className="max-w-prose whitespace-pre-wrap text-muted-foreground">{description}</p>
      )}
      {!!options.length && (
        <div className="space-y-3 border-y border-border py-5">
          {(["allergen", "dietary"] as const).map((kind) => (
            <MenuLabelOptions
              key={kind}
              legend={
                kind === "allergen" ? (labels.excludeAllergens ?? labels.allergens) : labels.dietary
              }
              labels={options.filter((label) => label.kind === kind)}
              value={selected[kind]}
              onChange={(value) => setFilters({ ...selected, [kind]: value })}
            />
          ))}
          <div className="flex flex-wrap items-center justify-between gap-2">
            <output className="text-sm text-muted-foreground" aria-live="polite">
              {hasFilters && !count ? labels.noFilterMatches : `${labels.matchingItems}: ${count}`}
            </output>
            <button
              className={outlineButton}
              disabled={!hasFilters}
              onClick={() => setFilters({ allergen: [], dietary: [] })}
            >
              {labels.clearFilters}
            </button>
          </div>
        </div>
      )}
      {sections.length === 0 && <p className="text-muted-foreground">{labels.emptyMenu}</p>}
      {filtered.map((section) => (
        <section key={section.id} aria-label={section.name} className="space-y-4">
          <CategoryHeading className="font-serif text-2xl font-semibold">
            {section.name}
          </CategoryHeading>
          {section.description && (
            <p className="max-w-prose whitespace-pre-wrap text-muted-foreground">
              {section.description}
            </p>
          )}
          <div>
            {section.items.map((item) => {
              const photoUrl = item.imageEntryId ? imageUrl?.(item.id) : undefined;
              const photoNode =
                MenuImage && photoUrl ? (
                  <MenuImage
                    src={photoUrl ?? ""}
                    alt={item.name}
                    className="h-20 w-full rounded-lg object-cover"
                  />
                ) : (
                  <ImageWithFallback
                    key={item.imageEntryId ?? "empty"}
                    src={photoUrl ?? ""}
                    alt={item.name}
                    fallbackLabel={labels.noPhoto}
                    className="h-20 w-full rounded-lg object-cover [&_figcaption]:px-1 [&_figcaption]:text-center [&_figcaption]:leading-tight"
                  />
                );
              return (
                <article
                  key={item.id}
                  className={cn(
                    "grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 gap-y-2 border-b border-border py-4 sm:gap-x-6",
                    withPhotos &&
                      "min-h-32 grid-cols-[minmax(0,1fr)_4rem_auto] sm:grid-cols-[minmax(0,1fr)_7.5rem_auto]",
                  )}
                >
                  <div className="min-w-0 space-y-2">
                    <DishHeading className="font-medium wrap-anywhere">{item.name}</DishHeading>
                    {item.description && (
                      <p className="text-sm whitespace-pre-wrap text-muted-foreground">
                        {item.description}
                      </p>
                    )}
                    {!!(item.labels.length || item.spiceLevel) && (
                      <div className="flex flex-wrap gap-1.5">
                        <MenuSpiceBadge level={item.spiceLevel ?? 0} labels={labels} />
                        {item.labels.map((label) => (
                          <MenuLabelBadge key={label.id} label={label} />
                        ))}
                      </div>
                    )}
                  </div>
                  {withPhotos &&
                    (photoUrl ? (
                      <Lightbox src={photoUrl} alt={item.name} className="h-20 w-full rounded-lg">
                        {photoNode}
                      </Lightbox>
                    ) : (
                      photoNode
                    ))}
                  <div className="min-w-12 space-y-2 text-right text-sm tabular-nums sm:min-w-24">
                    {item.sizes?.length ? (
                      <MenuSizePrices
                        sizes={item.sizes}
                        format={money}
                        className="max-w-24 sm:max-w-40"
                      />
                    ) : (
                      item.priceMinor !== null && <span>{money(item.priceMinor)}</span>
                    )}
                    {item.soldOut && (
                      <p className="text-xs text-status-pending-foreground">{labels.soldOut}</p>
                    )}
                  </div>
                </article>
              );
            })}
          </div>
        </section>
      ))}
    </section>
  );
}

import { useState } from "react";

import type { MenuFilters } from "./composed-public";
import { MenuLabelBadge } from "./label-badge";
import { MenuLabelOptions } from "./label-options";
import { getMenuFilterLabels } from "./label-presets";
import { menusLabels, type MenusLabels } from "./labels";
import { menuPriceFormatter } from "./price";
import { MenuPrintSymbols } from "./print-labels";
import { MenuSizePrices } from "./size-prices";
import { MenuSpiceBadge } from "./spice-badge";
import type { MenuCardView, MenuViewCategory, MenuViewLabel } from "./types";

const courses = ["starter", "main", "dessert"] as const;
const courseNames = {
  fr: { starter: "Entrées", main: "Plats", dessert: "Desserts" },
  en: { starter: "Starters", main: "Main courses", dessert: "Desserts" },
  de: { starter: "Vorspeisen", main: "Hauptgerichte", dessert: "Desserts" },
};

export function WeeklyMenu({
  data,
  locale,
  currency,
  currencyLabel = currency,
  labels: overrides,
  filterLabels,
  paper = false,
  filters,
  onFiltersChange,
}: {
  data: MenuCardView;
  locale: string;
  currency: string;
  currencyLabel?: string;
  labels?: Partial<MenusLabels>;
  filterLabels?: readonly MenuViewLabel[];
  paper?: boolean;
  filters?: MenuFilters;
  onFiltersChange?: (filters: MenuFilters) => void;
}) {
  const [localFilters, setLocalFilters] = useState<MenuFilters>({ allergen: [], dietary: [] });
  const selected = filters ?? localFilters;
  const labels = { ...menusLabels, ...overrides };
  const money = menuPriceFormatter(locale, currency);
  const hasPrices = data.categories.some((section) =>
    section.items.some((item) => item.priceMinor !== null || item.sizes?.length),
  );
  const options = getMenuFilterLabels(data.categories, locale, filterLabels);
  const lang = locale.startsWith("de") ? "de" : locale.startsWith("en") ? "en" : "fr";
  const days = [...(data.card.weekdays ?? [])].sort((a, b) => (a || 7) - (b || 7));
  const dayName = (day: number) =>
    new Intl.DateTimeFormat(locale, { weekday: "long", timeZone: "UTC" }).format(
      new Date(Date.UTC(2024, 0, 7 + day)),
    );
  const category = (day: number, course: string) =>
    data.categories
      .map((section) => ({
        ...section,
        items: section.items.filter(
          (item) =>
            paper ||
            (!item.labels.some(
              (label) => label.kind === "allergen" && selected.allergen.includes(label.id),
            ) &&
              selected.dietary.every((id) =>
                item.labels.some((label) => label.kind === "dietary" && label.id === id),
              )),
        ),
      }))
      .find(
        (section) =>
          section.id ===
          data.card.weeklySections?.find(
            (section) => section.day === day && section.course === course,
          )?.categoryId,
      );
  const content = (section: MenuViewCategory | undefined) =>
    section?.items.length ? (
      <ul className="space-y-3">
        {section.items.map((item) => (
          <li key={item.id} className="break-inside-avoid">
            <p className="font-medium wrap-anywhere">{item.name}</p>
            {item.description && (
              <p className="mt-1 text-sm whitespace-pre-wrap text-muted-foreground">
                {item.description}
              </p>
            )}
            {(!!item.labels.length || !!item.spiceLevel) && (
              <div className="mt-2 flex flex-wrap gap-1">
                {!!item.spiceLevel && (
                  <MenuSpiceBadge level={item.spiceLevel} labels={labels} iconOnly={paper} />
                )}
                {paper ? (
                  <MenuPrintSymbols labels={item.labels} />
                ) : (
                  item.labels.map((label) => <MenuLabelBadge key={label.id} label={label} />)
                )}
              </div>
            )}
            {item.soldOut && (
              <p className="mt-1 text-xs text-status-pending-foreground">{labels.soldOut}</p>
            )}
            {item.sizes?.length ? (
              <MenuSizePrices
                sizes={item.sizes}
                format={money}
                paper={paper}
                className="mt-1 text-sm"
              />
            ) : (
              item.priceMinor !== null && (
                <p className="mt-1 text-sm tabular-nums">{money(item.priceMinor)}</p>
              )
            )}
          </li>
        ))}
      </ul>
    ) : (
      <span
        aria-label={lang === "fr" ? "Aucun plat" : lang === "de" ? "Kein Gericht" : "No dish"}
        className="text-muted-foreground"
      >
        —
      </span>
    );
  return (
    <>
      {!paper && hasPrices && (
        <p className="mb-3 text-right text-sm text-muted-foreground">
          {labels.price} ({data.card.currencyLabel ?? currencyLabel})
        </p>
      )}
      {!paper && options.length > 0 && (
        <div className="mb-6 space-y-3 border-y border-border py-4">
          {(["allergen", "dietary"] as const).map((kind) => (
            <MenuLabelOptions
              key={kind}
              legend={
                kind === "allergen" ? (labels.excludeAllergens ?? labels.allergens) : labels.dietary
              }
              labels={options.filter((label) => label.kind === kind)}
              value={selected[kind]}
              onChange={(value) => {
                const next = { ...selected, [kind]: value };
                if (onFiltersChange) onFiltersChange(next);
                else setLocalFilters(next);
              }}
            />
          ))}
        </div>
      )}
      <div className={paper ? "" : "hidden md:block print:block"}>
        <table className="w-full table-fixed border-collapse text-left text-sm wrap-anywhere">
          <caption className="sr-only">{data.card.name}</caption>
          <thead>
            <tr>
              <th scope="col" className="w-24 border-b border-border p-3">
                <span className="sr-only">{lang === "fr" ? "Service" : "Course"}</span>
              </th>
              {days.map((day) => (
                <th
                  key={day}
                  scope="col"
                  className="border-b border-border p-3 font-semibold capitalize"
                >
                  {dayName(day)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {courses.map((course) => (
              <tr key={course}>
                <th scope="row" className="border-b border-border p-3 align-top font-medium">
                  {courseNames[lang][course]}
                </th>
                {days.map((day) => (
                  <td key={day} className="border-b border-border p-3 align-top">
                    {content(category(day, course))}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {!paper && (
        <div className="space-y-8 md:hidden print:hidden">
          {days.map((day) => (
            <section key={day} className="space-y-4">
              <h3 className="border-b border-border pb-2 font-serif text-xl font-semibold capitalize">
                {dayName(day)}
              </h3>
              {courses.map((course) => (
                <div key={course} className="grid grid-cols-[5.5rem_minmax(0,1fr)] gap-3">
                  <h4 className="text-sm text-muted-foreground">{courseNames[lang][course]}</h4>
                  <div className="text-sm">{content(category(day, course))}</div>
                </div>
              ))}
            </section>
          ))}
        </div>
      )}
    </>
  );
}

import { cn } from "@/components/utils/cn";

import { menuLabelColorClasses, MenuLabelSymbol } from "./label-badge";
import type { MenuViewLabel } from "./types";

function PaperLabelSymbol({ label }: { label: MenuViewLabel }) {
  return (
    <MenuLabelSymbol
      label={label}
      className={cn(
        "size-6 rounded-full p-1 print:[print-color-adjust:exact]",
        menuLabelColorClasses(label),
      )}
    />
  );
}

export function MenuPrintSymbols({ labels }: { labels: readonly MenuViewLabel[] }) {
  if (!labels.length) return null;
  return (
    <span className="inline-flex flex-wrap gap-1.5">
      {labels.map((label) => (
        <span key={label.id} title={label.name} className="inline-flex items-center">
          <PaperLabelSymbol label={label} />
          <span className="sr-only">{label.name}</span>
        </span>
      ))}
    </span>
  );
}

export function MenuPrintLegend({
  labels,
  title = "Legend",
}: {
  labels: readonly MenuViewLabel[];
  title?: string;
}) {
  const unique = [...new Map(labels.map((label) => [label.id, label])).values()];
  if (!unique.length) return null;
  return (
    <aside
      aria-label={title}
      className="mt-8 break-inside-avoid border-t border-border pt-4 text-[9pt]"
    >
      <h3 className="mb-2 font-semibold">{title}</h3>
      <ul className="flex flex-wrap gap-x-5 gap-y-2">
        {unique.map((label) => (
          <li key={label.id} className="inline-flex items-center gap-2">
            <PaperLabelSymbol label={label} />
            <span>{label.name}</span>
          </li>
        ))}
      </ul>
    </aside>
  );
}

import { cn } from "@/components/utils/cn";

import type { MenuViewItem } from "./types";

export function MenuSizePrices({
  sizes,
  format,
  className,
  paper,
}: {
  sizes: NonNullable<MenuViewItem["sizes"]>;
  format: (price: number) => string;
  className?: string;
  paper?: boolean;
}) {
  return (
    <dl className={cn("space-y-1 text-right tabular-nums", className)}>
      {sizes.map((size) => (
        <div
          key={size.id}
          className="grid grid-cols-[minmax(0,1fr)_max-content] items-baseline gap-x-2"
        >
          <dt className="wrap-anywhere whitespace-normal text-muted-foreground">{size.name}</dt>
          <dd data-menu-print-price={paper || undefined} className="whitespace-nowrap">
            {format(size.priceMinor)}
          </dd>
        </div>
      ))}
    </dl>
  );
}

import { transferDriveUpload, type DriveTransfer } from "@/components/plugins/drive/transfer";
import type { DriveClient } from "@/components/plugins/drive/types";
import type { MenuItem, MenuItemInput, MenusClient } from "@/components/plugins/menus/types";

export const dishPhotoMimeTypes = ["image/jpeg", "image/png", "image/webp"];
export const dishPhotoMaxBytes = 10_000_000;

export interface PendingDishPhoto {
  file: File;
  requestId: string;
  entryId?: string;
  completed?: boolean;
}

export function prepareDishPhoto(file: File): PendingDishPhoto {
  const requestId = crypto.randomUUID();
  const filename = Array.from(file.name.replace(/\.webp$/i, ""))
    .filter(
      (char) =>
        char !== "/" && char !== "\\" && char.charCodeAt(0) >= 32 && char.charCodeAt(0) !== 127,
    )
    .join("")
    .trim()
    .slice(0, 200);
  return {
    requestId,
    file: new File([file], `${filename || "photo"}-${requestId.slice(0, 8)}.webp`, {
      type: file.type,
    }),
  };
}

/** Keep the item and upload identities across retries after a partial save. */
export async function saveDishWithPhoto({
  client,
  drive,
  state,
  input,
  photo,
  visibleOnCreate,
  transfer = transferDriveUpload,
  signal,
}: {
  client: Pick<MenusClient, "save" | "create">;
  drive?: Pick<DriveClient, "prepareUpload" | "completeUpload">;
  state: { item?: MenuItem };
  input: MenuItemInput;
  photo?: PendingDishPhoto;
  visibleOnCreate: boolean;
  transfer?: DriveTransfer;
  signal: AbortSignal;
}): Promise<MenuItem> {
  if (photo && !drive) throw new Error("Photo storage is unavailable");
  if (!state.item) {
    state.item = await client.create(
      { ...input, imageEntryId: null, visible: photo ? false : input.visible },
      visibleOnCreate ? { visibleOnCreate: true } : undefined,
    );
    if (!photo) return state.item;
  }
  let imageEntryId = input.imageEntryId;
  if (photo && drive) {
    signal.throwIfAborted();
    const scope = { type: "menu-item", id: state.item.id };
    if (!photo.completed) {
      const ticket = await drive.prepareUpload({
        scope,
        parentId: null,
        requestId: photo.requestId,
        name: photo.file.name,
        size: photo.file.size,
        contentType: photo.file.type,
      });
      if (!ticket.entryId) throw new Error("The upload did not identify its file entry");
      photo.entryId = ticket.entryId;
      if (!ticket.completed) {
        await transfer(ticket, photo.file, { signal, onProgress: () => {} });
        signal.throwIfAborted();
        await drive.completeUpload({ scope, uploadId: ticket.id });
      }
      photo.completed = true;
    }
    if (!photo.entryId) throw new Error("The photo was not uploaded");
    imageEntryId = photo.entryId;
  }
  signal.throwIfAborted();
  state.item = await client.save(state.item.id, state.item.version, { ...input, imageEntryId });
  return state.item;
}

"use client";

import { UnlinkIcon } from "lucide-react";
import { useEffect, useId, useState, type ReactNode } from "react";

import { ImageCropDialog } from "@/components/image-crop";
import { ImageWithFallback } from "@/components/image-with-fallback";
import type { DriveClient } from "@/components/plugins/drive/types";
import type { MenusLabels } from "@/components/plugins/menus/labels";
import {
  dishPhotoMaxBytes,
  dishPhotoMimeTypes,
  prepareDishPhoto,
  type PendingDishPhoto,
} from "@/components/plugins/menus/save-with-photo";
import { field, outlineButton } from "@/components/plugins/menus/ui";
import { cn } from "@/components/utils/cn";

export function DishPhotoField({
  labels,
  pending,
  itemId,
  entryId,
  entryName,
  getPhotoUrl,
  driveClient,
  photo,
  onPick,
  onRemove,
  settings,
}: {
  labels: MenusLabels;
  pending: boolean;
  itemId?: string;
  entryId: string | null;
  entryName?: string;
  getPhotoUrl?: (itemId: string, entryId: string) => string | undefined;
  driveClient?: DriveClient;
  photo?: PendingDishPhoto;
  onPick: (photo: PendingDishPhoto) => void;
  onRemove: () => void;
  settings?: ReactNode;
}) {
  const id = `factory-dish-photo-${useId()}`;
  const [crop, setCrop] = useState<File | null>(null);
  const [dragging, setDragging] = useState(false);
  const [invalid, setInvalid] = useState(false);
  const sourceKey = photo?.requestId ?? (entryId && itemId ? `${itemId}:${entryId}` : "");
  const providedSrc = !photo && entryId && itemId ? getPhotoUrl?.(itemId, entryId) : undefined;
  const [preview, setPreview] = useState<{ key: string; url: string }>();

  useEffect(() => {
    let active = true;
    if (photo) {
      const url = URL.createObjectURL(photo.file);
      void Promise.resolve().then(() => {
        if (active) setPreview({ key: sourceKey, url });
      });
      return () => {
        active = false;
        URL.revokeObjectURL(url);
      };
    }
    if (providedSrc || !entryId || !itemId || !driveClient) return;
    void driveClient
      .getDownload({ scope: { type: "menu-item", id: itemId }, entryId })
      .then(({ url }) => {
        if (active) setPreview({ key: sourceKey, url });
      })
      .catch(() => {
        if (active) setPreview(undefined);
      });
    return () => {
      active = false;
    };
  }, [driveClient, entryId, itemId, photo, providedSrc, sourceKey]);

  const src = providedSrc ?? (preview?.key === sourceKey ? preview?.url : undefined) ?? "";
  function choose(file?: File) {
    if (!file) return;
    const valid =
      dishPhotoMimeTypes.includes(file.type) && file.size > 0 && file.size <= dishPhotoMaxBytes;
    setInvalid(!valid);
    if (valid) setCrop(file);
  }

  return (
    <fieldset className="min-w-0 space-y-3 rounded-xl border border-border p-4" disabled={pending}>
      <legend className="px-1 font-medium">
        {labels.photo}{" "}
        <span className="text-sm font-normal text-muted-foreground">{labels.photoOptional}</span>
      </legend>
      <div
        data-menu-photo-drop=""
        className={cn(
          "flex flex-wrap items-start gap-4 rounded-lg border-2 border-dashed p-3 transition-colors",
          dragging ? "border-primary bg-primary/10" : "border-border",
        )}
        onDragOver={(event) => {
          if (!driveClient || !event.dataTransfer.types.includes("Files")) return;
          event.preventDefault();
          event.dataTransfer.dropEffect = pending ? "none" : "copy";
          setDragging(!pending);
        }}
        onDragLeave={(event) => {
          if (
            !(
              event.relatedTarget instanceof Node &&
