                              {copy("Edit dish")}
                            </Dropdown.Item>
                            <Dropdown.SubmenuRoot>
                              <Dropdown.SubmenuTrigger disabled={locked || pending || searching}>
                                <MoveIcon aria-hidden="true" className="size-4" />
