export interface MenuItemEditorPageProps {
  /** Keep stable while editing; changing the client or item ID starts a fresh editor. */
  client: MenusClient;
  item?: MenuItem;
  categories: readonly MenuCategory[];
  labelsData: readonly MenuLabel[];
